    public static List<Profile> all(){return ALL;}
    public static Profile byId(String id){for(Profile p:ALL)if(p.id.equals(id))return p;return null;}
    public static Profile byEndpoint(String endpoint){for(Profile p:ALL)if(p.discoveryIdentity(endpoint))return p;return null;}
    public static Profile forSource(SourceRecord source){if(source==null||!source.catalog)return null;return byEndpoint(source.key);}
    public static String definitionSetHash(){List<String> hashes=new ArrayList<>();for(Profile p:ALL)hashes.add(p.id+":"+p.configSha);return SourceLimits.snapshotVersion(hashes.toArray(new String[0]));}
    public static List<Profile> six(){return selectedSix(false);}
    public static List<Profile> legacySix(){return selectedSix(true);}
    private static List<Profile> selectedSix(boolean legacy){List<Profile> list=new ArrayList<>();for(String id:legacy?List.of("elementy-science-explainers","biomolecula-articles","knife-articles","poisknews-biographies","forbes-open-articles","naukatv-articles"):List.of("rg-briefs","vedomosti-open-briefs","interfax-briefs","kommersant-briefs","elementy-science-explainers","biomolecula-articles"))list.add(Objects.requireNonNull(byId(id)));return Collections.unmodifiableList(list);}
